  "/ipad-keyboards": { h1: "Keyboards for iPad", headings: ["Keyboards for iPad", "Magic Keyboard for iPad Pro", "Thin and portable with multiple viewing angles", "Built-in trackpad with haptic feedback", "Function row", "Compatible with", "Magic Keyboard for iPad Air", "Function row"], paragraphs: ["Type it out. Take it with you.", "iPad keyboards provide an amazing typing experience and lightweight, durable protection for your iPad. And they attach to iPad magnetically — no need for switches, plugs, and pairing.", "Magic Keyboard for iPad Pro delivers an amazing typing and trackpad experience in a sleek, portable design with an aluminum palm rest. The keyboard includes a 14‑key function row, a USB‑C connector for pass‑through charging, and front and back protection for your iPad. The floating cantilever design smoothly adjusts to multiple viewing angles. A large glass trackpad expands how you can work with iPadOS and delivers haptic feedback for precision‑based workflows and Multi‑Touch gestures."] },
  "/ipad-mini": { h1: "iPad mini", headings: ["iPad mini", "Apple Intelligence.", "A17 Pro chip. Portable powerhouse.", "Apple Pencil Pro. Limitless creativity.", "Four gorgeous colors.", "Single-handedly awesome.", "Big-screen attitude. Ultraportable design.", "Apple Intelligence. Personal , private, powerful."], paragraphs: ["Introducing Apple Upgrade. Lease a new iPad with low monthly payments for 24 or 36 months and upgrade at the end of your term. § Learn more", "Built for Apple Intelligence.", "iPad mini has everything there is to love about iPad in a delightfully light, compact design. It features a 100 percent recycled aluminum enclosure and stunning all‑screen design , and it goes anywhere you go — fitting perfectly into a backpack or purse."] },
