  "/itunes": { h1: "iTunes", headings: ["iTunes", "iTunes is going places.", "iTunes", "Download the latest version for Windows.", "iTunes", "Download the latest version from the Microsoft Store.", "iTunes is going places.", "Music, TV, and podcasts take center stage."], paragraphs: ["Download the latest macOS for an all‑new entertainment experience. Your music, TV shows, movies, podcasts, and audiobooks will transfer automatically to the Apple Music, Apple TV, Apple Podcasts, and Apple Books apps where you’ll still have access to your favorite iTunes features, including purchases, rentals, and imports.", "The latest entertainment apps now come installed with the latest macOS. Upgrade today to get your favorite music, movies, TV shows, and podcasts. You can join Apple Music and stream — or download and play offline — millions of songs, ad‑free.", "Looking for Windows 32-bit?"] },
