  "/studio-display": { h1: "Studio Display", headings: ["Studio Display", "A sight to be bold.", "See what you can do.", "Camera and mics. A welcome sight. And sound.", "So they hear you. And only you.", "Hear. There. And everywhere.", "Superpower your studio.", "Displays well with others."], paragraphs: ["27-inch 5K Retina display", "12MP Center Stage camera with Desk View", "Six speakers with Spatial Audio"] },
  "/studio-display-xdr": { h1: "Studio Display XDR", headings: ["Studio Display XDR", "Pixel sharpener.", "Get the highlights.", "Take a closer look.", "Image Quality", "Most def.", "Mini-LED backlight.", "Exceptional brightness and contrast."], paragraphs: ["27-inch 5K Retina XDR display with mini-LED backlight. Precision for your vision.", "Pushes XDR further with 2000 nits peak HDR brightness, exceptional contrast, and P3 + Adobe RGB wide color gamut. Dream screen.", "120Hz refresh rate delivers ultrasmooth motion. And Adaptive Sync can adjust to varying frame rates. How refreshing."] },
  "/supply-chain": { h1: "Supply Chain Innovation", headings: ["Supply Chain Innovation", "People come first.", "Highlights", "33M+", "655K+", "10M+", "60%+", "30%"], paragraphs: ["Apple products are designed in California and built by people all over the world. We strive to uphold our high standards everywhere we operate, supporting the people and communities across our supply chain, and working to protect the planet we all share.", "supplier employees trained on their workplace rights since 2008", "supplier employees engaged about their workplace experience through interviews and anonymous surveys"] },
  "/support/exchange_repair": { h1: "Apple Service Programs", headings: ["Apple Service Programs", "Apple Footer", "Product Support", "Service and Repair", "Resources", "Connect"], paragraphs: ["Mac mini Service Program for No Power Issue June 13, 2025", "iPhone 14 Plus Service Program for Rear Camera Issue November 1, 2024", "15-inch MacBook Pro Battery Recall Program June 20, 2019"] },
  "/today": { h1: "Today at Apple", headings: ["Today at Apple", "Sorry, something went wrong.", "Select an Apple Store to see nearby events.", "Apple Footer", "Shop and Learn Shop and Learn", "Apple Wallet Apple Wallet", "Account Account", "Entertainment Entertainment"], paragraphs: ["Whether you're getting started with your new Apple products or pushing your skills further, find a session that's right for you.", "Please refresh the page or come back at a later time."] },
  "/today/calendar": { h1: "Calendar", headings: ["Calendar", "Sorry, something went wrong.", "Select an Apple Store to see nearby events.", "Apple Footer", "Shop and Learn Shop and Learn", "Apple Wallet Apple Wallet", "Account Account", "Entertainment Entertainment"], paragraphs: ["Get more from the products you love in our Get Started sessions. For select stores, explore a lineup of presenters under Featured Guests. Or, head out on a Tour to experiment with creative techniques.", "Please refresh the page or come back at a later time."] },
  "/today/camp": { h1: "Apple Camp", headings: ["Apple Camp", "Get Notified", "More ways to learn with Today at Apple", "Sorry, something went wrong.", "Sorry, something went wrong.", "Apple Footer", "Shop and Learn Shop and Learn", "Apple Wallet Apple Wallet"], paragraphs: ["This year at Apple Camp, kids ages 6–10 took their imaginations on an artistic adventure. They worked as a team to create superheroes that helped others using Freeform on iPad with Apple Pencil Pro. Sign up below to be the first to know about the next Apple Camp. In the meantime, explore more sessions for kids and families happening daily at your local Apple Store.", "Sign up below to receive a notification when Apple Camp registration opens.", "Discover free sessions, events, and activities in store. Happening every day. Sign up or drop by. You can even book a Today at Apple session just for your group."] },
  "/today/groups": { h1: "Book a session for your group.", headings: ["Book a session for your group.", "Selected Session", "Book this group session.", "Preferred Store and Time", "Contact Information", "Group Information", "Are you sure you want to cancel?", "Sorry, something went wrong."], paragraphs: ["Learn to code with students. Expand productivity skills with coworkers. Or make art with your community group. We can even get you started with accessibility features. Book a Today at Apple session just for your group at your Apple Store.", "You must be 18 years and over to register. By registering, you consent to the processing of your personal data by Apple and third parties involved in providing the session for reserving your spot, communicating reminders, and facilitating your and/or your group members’ participation in this session in accordance with Apple’s Privacy Policy. If your group includes minors, you represent that (a) you are the group members’ parent or legal guardian, or (b) you have obtained parental consent and any other necessary consents for each group member’s participation in the session.", "To learn more about privacy at Apple, visit Apple’s Privacy Policy ."] },
