  "/us/shop/goto/payment_plan": { h1: "Even more ways than ever to pay for the Apple products you love.", headings: ["Even more ways than ever to pay for the Apple products you love.", "Apple Card Monthly Installments", "Start shopping with Apple Card Monthly Installments today.", "iPhone", "Mac", "Watch", "iPad", "Apple Vision Pro"], paragraphs: ["Pay for your new Apple products over time, interest-free when you choose to check out at Apple with Apple Card Monthly Installments. footnote 1", "Now when you shop at Apple using Apple Card, you can pay monthly at 0% APR for your new iPhone, iPad, Mac, Apple Watch, Apple Vision Pro, and eligible accessories when you choose to check out with Apple Card Monthly Installments. And you’ll get 3% Daily Cash back — all up front.", "Get 3% Daily Cash back. All up front."] },
  "/us/shop/goto/personal_setup": { h1: "Join a Personal Setup session to get your new device ready.", headings: ["Join a Personal Setup session to get your new device ready.", "Already purchased?", "Start a session from your Orders page.", "The perks of buying from Apple.", "Need technical support? There’s a link for that, too.", "Footer", "footnotes", "Shop and Learn Shop and Learn +"], paragraphs: ["When you buy directly from Apple, you’ll get access to online, one-on-one sessions with a Specialist who will help you set up and make the most of your new device. Best of all, you can join whenever works for you, from wherever you are.", "Sign in Schedule a session (opens in a new window)", "If you purchased in store, contact us (Opens in a new window) to receive an email invitation."] },
  "/us/shop/goto/product/MW5G3": { h1: "Shop by Product", headings: ["Shop by Product", "Shop by Category", "Siri Remote", "Product Information", "Overview", "What’s in the Box", "Tech Specs", "Compatibility"], paragraphs: ["The Siri Remote (3rd generation) brings precise control to your Apple TV 4K.¹ Its touch-enabled clickpad lets you select titles, swipe through playlists, and use a circular gesture on the outer ring to find just the scene you’re looking for. With Siri, you can find what you want to watch using your voice. And the latest design includes a USB-C port to quickly recharge.", "Height: Height: 5.4 inches (136 mm)", "Width: Width: 1.4 inches (35 mm)"] },
  "/us/shop/goto/shipping_pickup": { h1: "Apple Delivery and Pickup", headings: ["Apple Delivery and Pickup", "Get the products you want, the way you want.", "Fast delivery.", "In-store pickup.", "We’re here to help.", "Join a Personal Setup session.", "Ship or drop off returns for free.", "Our commitment to protecting the planet."], paragraphs: ["Next-day delivery is available free for any in‑stock Mac, iPad, iPhone, AirPods or Apple Watch. And get free two-day delivery on almost everything else. In most metros, we also offer two-hour courier delivery of eligible items for a small fee.*", "It’s easy — we’ll guide you through every step of the process with emails and notifications. We’ll also send you details about joining a guided online session and returning trade‑in devices.", "Access free online, one-on-one sessions with a Specialist who will help you set up your device, transfer data, and customize your settings."] },
  "/us/shop/goto/smart_home/accessories": { h1: "TV & Home Accessories", headings: ["TV & Home Accessories", "In the spotlight.", "Apple TV 4K", "Pair up with HomePod.", "HomePod mini", "Build the smart home of your dreams.", "Home Theater", "tv"], paragraphs: ["Bring your favorite shows, apps, and services to the big screen with amazing sound and picture quality.", "Dial up the music you love and turn two HomePod speakers into one amazing stereo pair.", "Big sound that fits in anywhere. Available in five stunning colors."] },
  "/us/shop/goto/special_deals": { h1: "Certified Refurbished", headings: ["Certified Refurbished", "Shop by Refurbished Product", "Designed for an encore.", "Featured Products", "Why Refurbished", "AppleCare", "Savings that help reduce emissions.", "Free delivery and returns."], paragraphs: ["Apple Certified Refurbished products include a one‑year warranty, full functional testing, and savings up to 15%. Give an Apple device new life.", "Tested, certified, guaranteed. Check, check, and check.", "Protect your products individually with AppleCare+, or multiple products with AppleCare One."] },
  "/us/shop/goto/store": { h1: "Store", headings: ["Store", "The latest.", "Help is here.", "The Apple Store difference.", "Accessories.", "Elevated home theater sound.", "The Apple experience.", "Savings and offers."], paragraphs: ["Trade in your current device. Get credit toward a new one. Footnote ‡", "Enjoy two-hour delivery from an Apple Store, free delivery , or easy pickup. Footnote 1", "Pay in full, pay monthly, or lease and upgrade at the end of your term."] },
  "/us/shop/goto/trade_in": { h1: "Trade in. Upgrade. Save. Or recycle it for free.", headings: ["Trade in. Upgrade. Save. Or recycle it for free.", "Two easy ways to trade in.", "All the reasons to trade in with Apple. Including one very big 🌎ne.", "Easy in every way.", "Your privacy, protected.", "More ways to recycle.", "More questions? More answers.", "What devices are eligible for trade-in?"], paragraphs: ["With Apple Trade In, you can get great value for your current device and apply it toward a new one, online or at an Apple Store. If your device isn’t eligible for credit, we’ll recycle it — and any accessories you no longer use — securely and for free. It’s a great deal for you and a great way to protect the earth’s precious resources.", "Already started a trade-in? Check your trade-in status", "Trade in your way — online or at an Apple Store. From getting an estimate to returning your device, we’ll help every step of the way."] },
